  GROUP BY f.upid, f.ui_thread_utid ORDER BY count(*) DESC LIMIT 1
), long AS (
  SELECT s.ts,s.dur,s.track_id FROM slice s JOIN thread_track tt ON tt.id=s.track_id JOIN app ON app.ui_thread_utid=tt.utid
